// Per-operation pre-flight guards (Story 13.2a tier 3 / FR52). Each entry says "this
// field is mandatory when the server reports <driver> is X" — a condition set on a
// DIFFERENT operation, which n8n's displayOptions cannot see. execute() resolves it from
// the server ONLY when the field was left empty, and never blocks on a failed lookup.
interface PreflightGuard {
  field: string;
  lookupUrl: string;
  arrayPath?: string;
  matchParam?: string;
  driver: string;
  equals?: string;
  matchesRe?: string;
  message: string;
}
const PREFLIGHT_GUARDS: Record<string, readonly PreflightGuard[]> = {
  'add_signatory_to_document': [{"field":"phone","lookupUrl":"/api/v1/private/signature-requests/{signatureRequestId}","arrayPath":"documents","matchParam":"documentId","driver":"signatureType","equals":"ADVANCED","message":"This document is signed with signatureType ADVANCED, so the signatory Phone is mandatory (the signatory is authenticated by phone). Set Phone — e.g. +34600000000 — or use INTERPOSITION on the Add Document step."},{"field":"coordinates","lookupUrl":"/api/v1/private/signature-requests/{signatureRequestId}","arrayPath":"documents","matchParam":"documentId","driver":"filename","matchesRe":"\\.pdf$","message":"The document to sign is a PDF, so Coordinates are mandatory — activating the request fails without them. Set the on-page placement, e.g. [{\"x\":100,\"y\":100,\"page\":1}]."}],
 };

// GET query-parameter serialization style (Story 13.3/13.6). 'flat' spreads a
// top-level object (e.g. filter) into key=val params; 'bracket' uses qs-style
// filter[key]=val. Empty template value → default 'bracket'.
const QUERY_PARAM_STYLE: 'bracket' | 'flat' = ('flat' as string) === 'flat' ? 'flat' : 'bracket';
